   V(Unknown, 0)                                            \
-  V(NumberOrOddball, (1 << 1))                             \
-  V(Number, (1 << 2) | kNumberOrOddball)                   \
+  V(NumberOrOddball, (1 << 1) | kUnknown)                  \
+  V(NumberOrBoolean, (1 << 2) | kNumberOrOddball)          \
