+    DecodeNameSections();
+  }
+  // {index} should now always be in range, but let's be robust towards
+  // invalid parameter values.
+  if (index > type_names_.size() || type_names_[index].empty()) {
+    out << "$type" << index;
+    return;
+  }
+  StringT& name = type_names_[index];
+  out << '$';
+  out.write(name.data(), name.size());
