+size_t CanonicalTypeNamesProvider::DetectInlineStringThreshold() {
+  for (size_t i = 0; i < 32; i++) {
+    std::string s(i, 'c');
+    Address str = reinterpret_cast<Address>(&s);
+    Address data = reinterpret_cast<Address>(s.data());
