+template <typename uchar>
+V8_INLINE IndexParseResult TryParseArrayIndex(const uchar* chars,
+                                              uint32_t length, uint32_t& i,
+                                              uint32_t& index) {
+  DCHECK_GT(length, 0);
+  DCHECK_LE(length, String::kMaxIntegerIndexSize);
