+  // The leading character can only be a zero for the string "0"; otherwise this
+  // isn't a valid index string.
+  index = chars[0] - '0';
+  i = 1;
+  if (index > 9) return kNonIndex;
+  if (index == 0) {
+    if (length > 1) return kNonIndex;
+    DCHECK_EQ(length, 1);
+    return kSuccess;
+  }
