+      Isolate::central_stack_sp_offset());
+  __ Store(stack_data, central_stack_sp, StoreOp::Kind::RawAligned(),
+           MemoryRepresentation::UintPtr(), compiler::kNoWriteBarrier,
+           StackMemory::stack_switch_target_sp_offset());
