+             const ZoneUnorderedMap<OpIndex, ZoneVector<PackNode*>>& node_map) {
+  absl::flat_hash_set<PackNode const*> visited;
+
+  for (auto entry : node_map) {
+    for (auto pnode : entry.second) {
+      if (visited.find(pnode) != visited.end()) {
+        continue;
+      }
