+        // Finally: all good!
+        bool string_keys = key_type == wasm::kWasmExternRef;
+        return ElementAccessInfo(map, trap_value, target, string_keys, zone());
+      }
+      // Nothing else can occur on prototype chains.
+      UNREACHABLE();
+    }
+  }
+#endif  // V8_ENABLE_WEBASSEMBLY
+  return {};
